WHERE c.id IN ('741ebdd9-bd44-5741-b6de-2c66401c7d84', '3e708970-e4d9-5881-8deb-f5c3ba5d2477', '738f1245-906f-5fbc-a9a6-c5a4a91ab92e', '6494fa83-aec6-548d-bf26-399cecae232e') AND c.person_id <> (SELECT c.person_id FROM candidates c WHERE c.id IN ('741ebdd9-bd44-5741-b6de-2c66401c7d84', '3e708970-e4d9-5881-8deb-f5c3ba5d2477', '738f1245-906f-5fbc-a9a6-c5a4a91ab92e', '6494fa83-aec6-548d-bf26-399cecae232e') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
  AND ((SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) = 1
       OR NOT EXISTS (SELECT 1 FROM candidates c3 WHERE c3.person_id = c.person_id AND c3.id NOT IN ('741ebdd9-bd44-5741-b6de-2c66401c7d84', '3e708970-e4d9-5881-8deb-f5c3ba5d2477', '738f1245-906f-5fbc-a9a6-c5a4a91ab92e', '6494fa83-aec6-548d-bf26-399cecae232e')))
  AND NOT EXISTS (SELECT 1 FROM person_merges pm WHERE pm.duplicate->>'id' = c.person_id::text OR pm.keeper_ref = c.person_id)
  AND NOT EXISTS (SELECT 1 FROM audit_logs al WHERE al.action = 'CANDIDATE_SPLIT' AND al.entity_type = 'candidate' AND al.entity_id = c.id::text)
  AND NOT EXISTS (SELECT 1 FROM persons pp WHERE pp.id = c.person_id AND (pp.photo_url IS NOT NULL OR pp.bio IS NOT NULL OR pp.wikipedia_url IS NOT NULL OR pp.date_of_birth IS NOT NULL));

